/* Host harness for the real vs_cloud.c, focused on the paths the review
 * changed plus a regression pass over the normal session.
 */

#include <errno.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include "include/vs_cloud.h"

static int fails;

#define CHECK(c, ...)                                                     \
  do                                                                      \
    {                                                                     \
      printf((c) ? "  ok:   " : "  FAIL: ");                              \
      printf(__VA_ARGS__);                                                \
      printf("\n");                                                       \
      if (!(c)) fails++;                                                  \
    }                                                                     \
  while (0)

static unsigned char payload[512];

/* Open a session whose id selects a mock scenario. */

static int open_scenario(struct vs_cloud_session_s *s, const char *tag)
{
  memset(s, 0, sizeof(*s));
  snprintf(s->session_id, sizeof(s->session_id), "s-%s-1", tag);
  return vs_cloud_social_open(s);
}

static int run_to_close(struct vs_cloud_session_s *s, char *close_msg,
                        size_t cap)
{
  struct vs_cloud_media_packet_s p;
  struct vs_cloud_upload_s up;
  int ret;

  memset(&p, 0, sizeof(p));
  p.type = VS_CLOUD_MEDIA_IMAGE;
  p.data = payload;
  p.len = sizeof(payload);
  ret = vs_cloud_social_upload(s->session_id, &p, &up);
  if (ret < 0) return ret;

  return vs_cloud_social_finalize(s->session_id, close_msg, cap);
}

int main(void)
{
  struct vs_cloud_session_s s;
  struct vs_cloud_minutes_s m;
  struct vs_social_event_s ev[8];
  struct vs_cloud_upload_s up;
  struct vs_cloud_media_packet_s p;
  char close_msg[VS_CLOUD_MSG_ID_MAX];
  char image_msg[VS_CLOUD_MSG_ID_MAX];
  char full[131072];
  const char *ids[2];
  size_t n = 0;
  size_t i;
  int ret;

  for (i = 0; i < sizeof(payload); i++) payload[i] = (unsigned char)i;

  CHECK(vs_cloud_init() == 0, "init");

  /* ---------------- normal session, regression ---------------- */

  printf("\n== normal session ==\n");
  CHECK(open_scenario(&s, "normal") == 0, "open");

  memset(&p, 0, sizeof(p));
  p.type = VS_CLOUD_MEDIA_IMAGE;
  p.data = payload;
  p.len = sizeof(payload);
  CHECK(vs_cloud_social_upload(s.session_id, &p, &up) == 0, "upload image");
  CHECK(up.payload_sent, "bytes transferred to the presigned URL");
  snprintf(image_msg, sizeof(image_msg), "%s", up.msg_id);

  memset(&p, 0, sizeof(p));
  p.type = VS_CLOUD_MEDIA_AUDIO;
  p.data = payload;
  p.len = 128;
  CHECK(vs_cloud_social_upload(s.session_id, &p, &up) == 0, "upload audio");

  ids[0] = image_msg;
  ids[1] = up.msg_id;
  CHECK(vs_cloud_social_poll_event(s.session_id, ids, 2, ev, 8, &n) == 0,
        "poll");
  CHECK(n == 3, "two ids yielded three entries (%zu)", n);
  for (i = 0; i < n; i++)
    {
      if (ev[i].msg_event == VS_CLOUD_MSG_EVENT_IMAGE)
        {
          CHECK(ev[i].emotion == VS_EMOTION_TENSE && ev[i].extreme &&
                ev[i].confidence == 95 && ev[i].color == 0xe85d5d,
                "image entry: red/TENSE/extreme/conf 95");
          CHECK(strcmp(ev[i].display_text, "生气") == 0, "emotionDetail kept");
        }
      else if (ev[i].peer_state == VS_CLOUD_PEER_FAILED)
        CHECK(ev[i].raw_status == 32 &&
              strcmp(ev[i].log, "音频无有效声音") == 0,
              "server code 32 mapped, log kept");
    }

  CHECK(vs_cloud_social_finalize(s.session_id, close_msg,
                                 sizeof(close_msg)) == 0, "finalize");
  CHECK(vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0) ==
        -EAGAIN, "first close poll is -EAGAIN (status 40)");
  ret = vs_cloud_social_get_result(s.session_id, close_msg, &m, full,
                                  sizeof(full));
  CHECK(ret == 0, "second close poll succeeded (%d)", ret);
  CHECK(m.calm == 25 && m.happy == 25 && m.tense == 50,
        "1 calm / 1 happy / 2 tense -> %u/%u/%u", m.calm, m.happy, m.tense);
  CHECK(m.emotion_samples == 4 && m.audio_samples == 2, "sample counts");
  CHECK(strstr(full, "emotionTimeline") != NULL, "full json captured");

  /* ---------------- rounding: no tense frames ---------------- */

  printf("\n== rounding with no tense frames ==\n");
  CHECK(open_scenario(&s, "happy") == 0, "open");
  CHECK(run_to_close(&s, close_msg, sizeof(close_msg)) == 0, "run to close");
  (void)vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0);
  ret = vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0);
  CHECK(ret == 0, "close poll succeeded (%d)", ret);
  printf("  calm=%u happy=%u tense=%u\n", m.calm, m.happy, m.tense);
  CHECK(m.tense == 0, "tense is 0, not a rounding artefact");
  CHECK(m.calm + m.happy + m.tense == 100, "still totals 100");

  /* ---------------- close msgId answered with an image entry -------- */

  printf("\n== close msgId answered with the wrong event ==\n");
  CHECK(open_scenario(&s, "wrongev") == 0, "open");
  CHECK(run_to_close(&s, close_msg, sizeof(close_msg)) == 0, "run to close");
  (void)vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0);
  ret = vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0);
  CHECK(ret == -EAGAIN,
        "image entry under the close msgId is not accepted (%d)", ret);
  CHECK(m.tts_url[0] == '\0' && m.summary[0] == '\0',
        "no half-built minutes handed back");

  /* ---------------- entry with no msgEvent ---------------- */

  printf("\n== getResult entry with no msgEvent ==\n");
  CHECK(open_scenario(&s, "nomsgev") == 0, "open");
  memset(&p, 0, sizeof(p));
  p.type = VS_CLOUD_MEDIA_IMAGE;
  p.data = payload;
  p.len = sizeof(payload);
  CHECK(vs_cloud_social_upload(s.session_id, &p, &up) == 0, "upload");
  ids[0] = up.msg_id;
  ret = vs_cloud_social_poll_event(s.session_id, ids, 1, ev, 8, &n);
  CHECK(ret == 0, "poll itself succeeds (%d)", ret);
  CHECK(n == 0, "the entry is dropped, not guessed as an image (%zu)", n);

  /* ---------------- response larger than the buffer ---------------- */

  printf("\n== getResult body past the response budget ==\n");
  CHECK(open_scenario(&s, "huge") == 0, "open");
  CHECK(run_to_close(&s, close_msg, sizeof(close_msg)) == 0, "run to close");
  (void)vs_cloud_social_get_result(s.session_id, close_msg, &m, NULL, 0);
  ret = vs_cloud_social_get_result(s.session_id, close_msg, &m, full,
                                  sizeof(full));
  CHECK(ret == -E2BIG, "over-capacity body is -E2BIG, not -EPROTO (%d)", ret);

  /* ---------------- mock presigned URL ---------------- */

  printf("\n== mock presigned URL ==\n");
  CHECK(open_scenario(&s, "mockurl") == 0, "open");
  memset(&p, 0, sizeof(p));
  p.type = VS_CLOUD_MEDIA_IMAGE;
  p.data = payload;
  p.len = sizeof(payload);
  ret = vs_cloud_social_upload(s.session_id, &p, &up);
  CHECK(ret == 0, "registration still succeeds (%d)", ret);
  CHECK(up.msg_id[0] != '\0', "msg id usable: %s", up.msg_id);
  CHECK(!up.payload_sent, "payload_sent reports that no bytes moved");
  (void)vs_cloud_social_finalize(s.session_id, close_msg, sizeof(close_msg));

  /* ---------------- input validation ---------------- */

  printf("\n== validation ==\n");
  {
    /* A msgId longer than the buffer that has to hold it must be refused,
     * not truncated into something that matches nothing.
     */

    const char *toolong[1] =
      { "0123456789012345678901234567890123456789012345" };

    CHECK(vs_cloud_social_poll_event(s.session_id, toolong, 1, ev, 8, &n) ==
          -EINVAL, "over-long msgId refused");
  }

  {
    const char *hostile[1] = { "1\",\"deviceId\":\"x" };

    CHECK(vs_cloud_social_poll_event(s.session_id, hostile, 1, ev, 8, &n) ==
          -EINVAL, "msgId containing a quote refused");
  }

  CHECK(vs_cloud_social_open(NULL) == -EINVAL, "open(NULL)");
  CHECK(vs_cloud_social_finalize("has spaces", close_msg,
                                 sizeof(close_msg)) == -EINVAL,
        "session id with spaces refused");
  {
    struct vs_cloud_media_packet_s empty;

    memset(&empty, 0, sizeof(empty));
    CHECK(vs_cloud_social_upload(s.session_id, &empty, &up) == -EINVAL,
          "empty packet refused");
  }

  /* ---------------- full batch of 16 ids ---------------- */

  printf("\n== a full batch at the declared limit ==\n");
  {
    /* 16 identifiers of the maximum length the API accepts.  The point is
     * that the query buffers are sized from those two constants, so the
     * advertised batch size is one that can actually be sent: this used to
     * fail -E2BIG.
     */

    const char *batch[16];
    char storage[16][VS_CLOUD_MSG_ID_MAX];

    for (i = 0; i < 16; i++)
      {
        memset(storage[i], 'a', VS_CLOUD_MSG_ID_MAX - 1);
        storage[i][VS_CLOUD_MSG_ID_MAX - 1] = '\0';
        snprintf(storage[i], 4, "%03zu", i);
        storage[i][3] = 'a';
        batch[i] = storage[i];
      }

    ret = vs_cloud_social_poll_event(s.session_id, batch, 16, ev, 8, &n);
    CHECK(ret == 0, "16 max-length ids sent without -E2BIG (%d)", ret);
  }

  printf("\n%s (%d failure%s)\n", fails ? "FAILURES" : "ALL PASSED", fails,
         fails == 1 ? "" : "s");
  return fails ? 1 : 0;
}

